import math

def solve():
    L = 100
    total = 0
    for a in range(-50, 51):
        for b in range(-50, 51):
            s2 = a**2 + a*b + b**2
            if s2 == 0:
                continue
            s = 2 * math.sqrt(s2)
            if s > L:
                continue

            r_x = b - a
            r_y = -(a + b) * math.sqrt(3)

            max_y = -float('inf')
            curr_x, curr_y = r_x, r_y
            for _ in range(6):
                max_y = max(max_y, curr_y)
                new_x = curr_x/2 - curr_y * math.sqrt(3)/2
                new_y = curr_x * math.sqrt(3)/2 + curr_y/2
                curr_x, curr_y = new_x, new_y

            dh = max_y
            L_prime = L - 2 * dh / math.sqrt(3)
            L_int = int(L_prime + 1e-9)

            count = 0
            for n in range(-L_int, L_int + 1):
                m_min = max(-L_int, -L_int - n)
                m_max = min(L_int, L_int - n)
                if m_max >= m_min:
                    count += (m_max - m_min + 1)

            if a % 2 == 0 and b % 2 == 0:
                total += count // 6
            elif a % 2 == 0 and b % 2 != 0:
                total += count // 4
            elif a % 2 != 0 and b % 2 != 0:
                total += count // 4
            else:
                total += count // 2
    print(total)

solve()
